// ── 요약 만들기 ──────────────────────────────────────────────────────────────
// 지난 7일 거절을 norm_key 로 묶어 빈도순으로 줄 세운다.
//
// [거절이 0건인 주에는 보내지 않는다]
// 빈 배열을 돌려 Discord 노드를 아예 돌리지 않는다. "이번 주 0건" 은 할 일이 없다는
// 뜻이고, 할 일 없는 알림이 매주 오면 할 일 있는 알림도 같이 안 읽히게 된다.
// 봇이 죽어서 0건인 경우는 ③ 오류 알림이 따로 말해 준다 — 이 리포트가 할 일이 아니다.
//
// [종류(게이트/자체)로 나누지 않는다]
// 사용자가 할 일은 둘 다 "노트를 쓴다" 로 같다. 갈라 놓으면 같은 주제가 두 절로 흩어져
// 빈도가 낮아 보인다. 대신 **행동이 실제로 갈리는 축**으로 한 번만 가른다:
//   새 노트  — 질문의 내용어가 볼트에 거의 없다(lexHit < 0.5). 없는 주제다.
//   보강     — 어휘는 볼트에 있는데(lexHit >= 0.5) 막혔거나, 모델이 그 노트를 읽고도
//              "내용 없다" 고 답했다. 노트는 있고 그 안의 **항목**이 빠진 것이다.
// lexHit 을 쓰는 이유: ⓪ `근거 판정` 에서 거리(best2mean)와 직교하는 유일한 축이고,
// 뜻이 그대로 "질문의 내용어가 회수된 노트에 문자 그대로 나오는가" 다. 거리 임계값으로
// 가르면 "쿠버네티스"(0.60)와 "러스트"(0.53)가 갈리는데 둘 다 볼트에 없는 주제다.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.norm_key);
if (!rows.length) return [];

const LEX_HAS = 0.5;   // 내용어 절반 이상이 회수된 노트에 문자 그대로 있으면 "볼트에 있다"

const groups = new Map();
for (const r of rows) {
  let g = groups.get(r.norm_key);
  if (!g) {
    g = { key: r.norm_key, n: 0, gate: 0, self: 0, qs: [], users: new Set(),
          lex: [], nearest: new Map(), picked: new Map(), lead: '', last: 0 };
    groups.set(r.norm_key, g);
  }
  g.n++;
  if (r.kind === 'gate') g.gate++; else g.self++;
  const q = String(r.raw_question || '').replace(/\s+/g, ' ').trim();
  if (q && g.qs.indexOf(q) === -1) g.qs.push(q);
  if (r.user_hash) g.users.add(r.user_hash);
  if (typeof r.lex_hit === 'number') g.lex.push(r.lex_hit);
  const bump = (m, k) => { if (k && k !== '없음') m.set(k, (m.get(k) || 0) + 1); };
  bump(g.nearest, r.nearest);
  if (r.kind === 'self') { bump(g.picked, r.picked_notes); if (!g.lead) g.lead = r.answer_lead || ''; }
  const t = new Date(r.asked_at).getTime();
  if (isFinite(t) && t > g.last) g.last = t;
}

const top = (m) => { let k = '', n = 0; for (const [a, b] of m) if (b > n) { k = a; n = b; } return k; };
const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);

const list = [...groups.values()].map((g) => {
  const lex = mean(g.lex);
  // 자체 거절은 그 자체로 "노트는 읽었는데 항목이 없다" 는 뜻이라 무조건 보강이다.
  const gap = g.self > 0 || (lex !== null && lex >= LEX_HAS);
  return { ...g, lex, gap };
})
  // 많이 물은 것 먼저. 같은 횟수면 볼트에서 먼 것(= 더 확실히 없는 노트) 먼저.
  .sort((a, b) => b.n - a.n || ((a.lex ?? 1) - (b.lex ?? 1)) || b.last - a.last);

const d = (ms) => new Date(ms + 9 * 3600e3).toISOString().slice(5, 10).replace('-', '/');
const now = Date.now();
const nNew = list.filter((g) => !g.gap).length;
const nGap = list.length - nNew;

const head = [
  '🗒️ **못 답한 질문 주간 요약** · ' + d(now - 7 * 864e5) + '–' + d(now),
  '거절 ' + rows.length + '건 · 서로 다른 질문 ' + list.length + '개' +
    '  (새 노트 ' + nNew + ' · 기존 노트 보강 ' + nGap + ')',
  '',
];

const MAX = 12;
const body = list.slice(0, MAX).map((g, i) => {
  const rep = g.qs[0] || g.key;
  const times = g.n > 1 ? ' **×' + g.n + '**' : '';
  const who = g.users.size > 1 ? ' · ' + g.users.size + '명' : '';
  const l1 = (i + 1) + '. ' + (g.gap ? '🩹' : '🆕') + ' ' + rep.slice(0, 64) + times + who;

  // 둘째 줄이 곧 할 일이다.
  let l2;
  if (g.self > 0) {
    const note = top(g.picked) || top(g.nearest);
    l2 = '   ' + (note || '?') + ' 를 읽고도 "관련 내용 없다" — 그 노트에 빠진 항목';
  } else if (g.gap) {
    l2 = '   ' + (top(g.nearest) || '?') + ' 에 어휘는 있다 — 그 노트를 보강 (어휘 ' +
         (g.lex === null ? '?' : g.lex.toFixed(2)) + ')';
  } else {
    l2 = '   볼트에 없는 주제 (가장 가까운 노트 ' + (top(g.nearest) || '없음') + ')';
  }
  // 말만 바꿔 다시 물은 게 있으면 하나만 더 보여 준다 — 묶임이 맞는지 눈으로 검증된다.
  const l3 = g.qs.length > 1
    ? '   ↳ "' + g.qs[1].slice(0, 48) + '"' + (g.qs.length > 2 ? ' 외 ' + (g.qs.length - 2) : '')
    : '';
  return [l1, l2, l3].filter(Boolean).join('\n');
});

const tail = [];
if (list.length > MAX) tail.push('… 외 ' + (list.length - MAX) + '개');
tail.push('', '🆕 새로 쓸 노트  ·  🩹 있는 노트에 보탤 항목');

const content = head.concat(body).concat(tail).join('\n');

// ── 볼트 로그 블록 ─────────────────────────────────────────────────────────
// 2026-09-16: Discord 로만 보내면 나중에 공부할 때 채널을 뒤져야 한다.
// 같은 내용을 볼트에 노트로 남긴다 — 옵시디언 안에서 검색되고 링크된다.
// 위키링크로 적어 해당 노트에서 역링크가 보이게 한다.
const wl = (p) => {
  const base = String(p || '').split('/').pop().replace(/\.md$/, '');
  return base ? '[[' + base + ']]' : '?';
};
const today = new Date(now + 9 * 3600e3).toISOString().slice(0, 10);
const logLines = list.map((g) => {
  const rep = (g.qs[0] || g.key).slice(0, 70);
  const times = g.n > 1 ? ` ×${g.n}` : '';
  if (g.self > 0) {
    return `- 🩹 ${rep}${times} — ${wl(top(g.picked) || top(g.nearest))} 보강 필요 (읽고도 "관련 내용 없다")`;
  }
  if (g.gap) {
    return `- 🩹 ${rep}${times} — ${wl(top(g.nearest))} 보강 필요 (어휘 ${g.lex === null ? '?' : g.lex.toFixed(2)})`;
  }
  return `- 🆕 ${rep}${times} — 노트 필요 (가장 가까운 노트 ${wl(top(g.nearest))})`;
});
const logBlock = logLines.length
  ? `## ${today}\n` + logLines.join('\n') + '\n'
  : '';

return [{ json: { content: content.slice(0, 1900), total: rows.length, groups: list.length,
                  newNotes: nNew, gaps: nGap, logBlock, today } }];

// ── 볼트 로그 합치기 ──────────────────────────────────────────────────────
// `요약 만들기` 가 만든 이번 주 블록을 기존 로그 **맨 위**에 얹는다.
// Discord 요약과 같은 내용이지만, 볼트에 두면 옵시디언 안에서 검색되고
// 위키링크로 해당 노트에서 역링크가 보인다 — 나중에 공부할 때 그게 쓸모다.
//
// [입력]
//   $input        `기존 로그 읽기` 의 binary.data — 파일이 없으면 비어 있다
//                 (그 노드는 onError=continueRegularOutput 이라 없어도 안 멈춘다)
//   요약 만들기    logBlock(이번 주 블록) · today(YYYY-MM-DD)
// [출력]
//   binary.data   합쳐진 파일 전문 — `볼트에 쓰기` 가 그대로 쓴다
//   json          경로와 길이 (실행 기록에서 눈으로 확인하려고)

// 파일이 없을 때 처음 만들 머리말. 여기 문구가 노트 맨 위에 남는다.
const HEAD = [
  '# 못 답한 질문 로그',
  '',
  '> 봇이 답하지 못한 질문을 주 1회 쌓는다. 새 항목이 위에 온다.',
  '> 🆕 = 볼트에 없는 주제 · 🩹 = 노트는 있는데 그 항목이 빠졌다',
  '> 자동 생성 — `Obsidian RAG — ⑤ 거절 질문 주간 요약`',
  '',
].join('\n');

const summary = $('요약 만들기').first().json;
const block = String(summary.logBlock || '');

// 거절이 0건인 주에는 파일을 아예 건드리지 않는다.
// 빈 항목을 남기면 로그가 "아무 일도 없었다" 로 채워져 읽을 값이 떨어진다.
if (!block.trim()) {
  return [];
}

// ── 기존 내용 읽기 ───────────────────────────────────────────────────────
// 첫 실행이면 파일이 없다. 그 경우 binary 가 통째로 비어 예외가 나므로 삼킨다.
let existing = '';
try {
  const bin = $input.first().binary && $input.first().binary.data;
  if (bin) {
    existing = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf-8');
  }
} catch (e) {
  existing = '';
}

let body = existing.trim() ? existing : HEAD;

// ── 같은 날짜 블록은 갈아끼운다 ──────────────────────────────────────────
// 수동 실행(webhook/refusal-digest-now)을 하루에 여러 번 돌려도
// 같은 날짜가 여러 번 쌓이지 않게 한다. 다음 `## ` 직전까지가 한 블록이다.
const sameDay = new RegExp('^## ' + summary.today + '\\n[\\s\\S]*?(?=\\n## |$)', 'm');
body = body.replace(sameDay, '').replace(/\n{3,}/g, '\n\n');

// ── 맨 위에 얹기 ────────────────────────────────────────────────────────
// 첫 날짜 블록 바로 앞에 끼운다. 블록이 하나도 없으면(=첫 실행) 끝에 붙인다.
const firstBlock = body.indexOf('\n## ');
const merged = firstBlock >= 0
  ? body.slice(0, firstBlock + 1) + block + '\n' + body.slice(firstBlock + 1)
  : body.replace(/\s*$/, '\n\n') + block;

// 끝을 늘 개행 하나로 맞춘다. 이게 없으면 실행마다 파일 끝이 1바이트씩 흔들려
// 옵시디언 동기화가 매번 변경으로 잡는다.
const text = merged.replace(/\s*$/, '\n');

const fileName = 'rag-unanswered.md';
return [{
  json: { path: '/home/node/vault/' + fileName, bytes: text.length },
  binary: {
    data: await this.helpers.prepareBinaryData(
      Buffer.from(text, 'utf-8'), fileName, 'text/markdown'),
  },
}];

// 주기 작업의 "지금이 차례인가" 게이트.
//
// 이 맥북은 00~06시 KST 에 자서 **고정 시각 스케줄이 한 번도 뜬 적이 없다**
// (2026-09-18 실측: 14일 보존 기간 안에 ④·⑤ 의 trigger 모드 실행 0건.
//  가동률이 가장 높은 22시도 64% 라 어느 고정 시각도 안전하지 않다).
//
// 그래서 6시간마다 뜨고, 앞의 `주간 차례 확인` 이 차례를 **원자적으로** 집는다:
// 7일이 안 지났으면 그 INSERT ... ON CONFLICT ... WHERE 가 0행을 돌려주고,
// 여기서 걸러져 아래로 아무것도 안 내려간다. 조회하고 나서 쓰는(check-then-act)
// 방식이 아니라 한 쿼리라 동시 실행이 겹쳐도 두 번 돌지 않는다.
//
// 수동 실행(웹훅) 경로는 이 게이트를 **지나지 않는다** — 언제든 바로 돈다.
return $input.all().filter((i) => i && i.json && i.json.job);
